-- Bootstrap schema is also generated by SQLAlchemy Base.metadata.create_all.
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email VARCHAR(120) UNIQUE NOT NULL,role VARCHAR(20) NOT NULL,password_hash VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS processes(id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,temperature FLOAT NOT NULL,dwell FLOAT NOT NULL,pressure FLOAT NOT NULL,note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS devices(id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL,note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS samples(id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,process_id INTEGER NOT NULL REFERENCES processes(id),lot VARCHAR(60) NOT NULL,force FLOAT NOT NULL,flagged BOOLEAN NOT NULL,note TEXT NOT NULL,device_id INTEGER REFERENCES devices(id),disposition VARCHAR(20) NOT NULL DEFAULT 'normal',hold_reason TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS gauge_studies(id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,device_id INTEGER NOT NULL REFERENCES devices(id),title VARCHAR(120) UNIQUE NOT NULL,standard_count INTEGER NOT NULL,operators JSON NOT NULL,replicate_count INTEGER NOT NULL,thresholds JSON NOT NULL,status VARCHAR(20) NOT NULL,result JSON,error TEXT NOT NULL,published BOOLEAN NOT NULL,published_at VARCHAR(40) NOT NULL,published_by VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS gauge_readings(id SERIAL PRIMARY KEY,study_id INTEGER NOT NULL REFERENCES gauge_studies(id),standard_index INTEGER NOT NULL,standard_label VARCHAR(60) NOT NULL,operator VARCHAR(60) NOT NULL,replicate INTEGER NOT NULL,value FLOAT,UNIQUE(study_id,standard_index,operator,replicate));
CREATE TABLE IF NOT EXISTS release_ledger(id SERIAL PRIMARY KEY,study_id INTEGER NOT NULL REFERENCES gauge_studies(id),sample_id INTEGER NOT NULL REFERENCES samples(id),device_id INTEGER NOT NULL REFERENCES devices(id),released_by VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL,UNIQUE(study_id,sample_id));
CREATE TABLE IF NOT EXISTS assessments(id SERIAL PRIMARY KEY,title VARCHAR(120) UNIQUE NOT NULL,lot VARCHAR(60) NOT NULL,status VARCHAR(20) NOT NULL,snapshot JSON NOT NULL,result JSON,error TEXT NOT NULL,recommendation TEXT NOT NULL,selected_process_id INTEGER REFERENCES processes(id),approved BOOLEAN NOT NULL,approved_by VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id SERIAL PRIMARY KEY,actor VARCHAR(120) NOT NULL,action VARCHAR(200) NOT NULL,status INTEGER NOT NULL,created_at VARCHAR(40) NOT NULL);
